"use server";

// Generated by philote from page /swipe. Do not edit.
import { redirect } from "next/navigation";

import { swipe } from "@/lib/api";
import { type FormState, bool, failed, text } from "@/lib/form";

export async function submit(_state: FormState, data: FormData): Promise<FormState> {
    const result = await swipe({
        horse: text(data, "horse"),
        target: text(data, "target"),
        liked: bool(data, "liked"),
    });
    if (!result.ok) {
        return failed(data, result.error, result.issues);
    }
    redirect("/matches");
}
